import{_ as t,c as e,o as a,a4 as r}from"./chunks/framework.BYxathSa.js";const g=JSON.parse('{"title":"Q2：什么是 JSX？为什么在 React 中使用它？","description":"","frontmatter":{},"headers":[],"relativePath":"react/q2.md","filePath":"react/q2.md","lastUpdated":null}'),c={name:"react/q2.md"},o=r('<h1 id="q2-什么是-jsx-为什么在-react-中使用它" tabindex="-1">Q2：什么是 JSX？为什么在 React 中使用它？ <a class="header-anchor" href="#q2-什么是-jsx-为什么在-react-中使用它" aria-label="Permalink to &quot;Q2：什么是 JSX？为什么在 React 中使用它？&quot;">​</a></h1><p>JSX 是 JavaScript 的一种语法扩展，看起来类似 HTML，它允许在 JavaScript 中直接编写 UI 结构。JSX 最终会被 Babel 编译为 <code>React.createElement</code> 调用，生成虚拟 DOM 节点。</p><p><strong>使用原因</strong>：</p><ul><li><strong>可读性强</strong>：用类似 HTML 的结构描述 UI，比手写 <code>React.createElement</code> 更加直观和易于维护。</li><li><strong>表达式嵌入</strong>：可通过 <code>{ }</code> 嵌入任意 JavaScript 表达式，动态生成内容。</li><li><strong>防止注入攻击</strong>：React DOM 在渲染前会转义 JSX 中的所有值，有效避免 XSS。</li><li><strong>编译优化</strong>：JSX 是编译时的语法糖，可以与虚拟 DOM 渲染流程完美结合。</li></ul>',4),s=[o];function n(l,i,_,d,p,S){return a(),e("div",null,s)}const h=t(c,[["render",n]]);export{g as __pageData,h as default};
